  "gamelist.tp_n_causeway": "گذرگاه غول، ایرلند شمالی",
  "gamelist.tp_n_crooked": "جنگل کج، لهستان",
  "gamelist.tp_n_danakil": "فرورفتگی دناکیل، اتیوپی",
  "gamelist.tp_n_darvaza": "دهانه‌ی گازی دروازه، ترکمنستان",
